object ItemAttributesRequestData {

  def validated(d8a : ItemAttributesRequestData, failFast : Boolean) : scala.util.Try[ItemAttributesRequest] = d8a.validated(failFast)

  def fromJson(jason : ujson.Value) : ItemAttributesRequestData = try {
        val data = read[ItemAttributesRequestData](jason)
        data
    } catch {
      case NonFatal(e) => sys.error(s"Error creating ItemAttributesRequestData from json '$jason': $e")
  }

  def fromJsonString(jason : String) : ItemAttributesRequestData = {
        val parsed = try {
           read[ujson.Value](jason)
        } catch {
          case NonFatal(e) => sys.error(s"Error parsing json '$jason': $e")
        }
        fromJson(parsed)
  }

  def manyFromJsonString(jason : String) : Seq[ItemAttributesRequestData] = try {
        read[List[ItemAttributesRequestData]](jason)
    } catch {
        case NonFatal(e) => sys.error(s"Error parsing json '$jason' as list: $e")
    }

  def manyFromJsonStringValidated(jason : String, failFast : Boolean = false) : Try[Seq[ItemAttributesRequest]] = {
      Try(manyFromJsonString(jason)).flatMap { list =>
        list.zipWithIndex.foldLeft(Try(Vector[ItemAttributesRequest]())) {
          case (Success(list), (next, i)) => 
            next.validated(failFast) match {
              case Success(ok) => Success(list :+ ok)
              case Failure(err) => Failure(new Exception(s"Validation error on element $i: ${err.getMessage}", err))
            }
          case (fail, _)  => fail
        }
      }
    }

  def mapFromJsonString(jason : String) : Map[String, ItemAttributesRequestData] = try {
        read[Map[String, ItemAttributesRequestData]](jason)
    } catch {
        case NonFatal(e) => sys.error(s"Error parsing json '$jason' as map: $e")
    }


  def mapFromJsonStringValidated(jason : String, failFast : Boolean = false) : Try[Map[String, ItemAttributesRequest]] = {
     Try(mapFromJsonString(jason)).flatMap { map =>
       map.foldLeft(Try(Map[String, ItemAttributesRequest]())) {
         case (Success(map), (key, next)) =>
           next.validated(failFast) match {
             case Success(ok) => Success(map.updated(key, ok))
             case Failure(err) => Failure(new Exception(s"Validation error on element $key: ${err.getMessage}", err))
           }
         case (fail, _) => fail
       }
     }
  }
}

